// ── Composant : Signature ──────────────────────────────────────────────────
function SignaturePad({ value, onChange }) {
  const canvasRef = useRef(null);
  const drawing = useRef(false);
  const [hasSig, setHasSig] = useState(!!value);

  useEffect(() => {
    if (value && canvasRef.current) {
      const img = new Image();
      img.onload = () => {
        const ctx = canvasRef.current.getContext("2d");
        ctx.clearRect(0, 0, 400, 150);
        ctx.drawImage(img, 0, 0);
      };
      img.src = value;
    }
  }, []);

  const pos = (e, canvas) => {
    const r = canvas.getBoundingClientRect();
    const src = e.touches ? e.touches[0] : e;
    return { x: src.clientX - r.left, y: src.clientY - r.top };
  };

  const start = (e) => { e.preventDefault(); drawing.current = true; const c = canvasRef.current; const ctx = c.getContext("2d"); const { x, y } = pos(e, c); ctx.beginPath(); ctx.moveTo(x, y); };
  const move = (e) => { e.preventDefault(); if (!drawing.current) return; const c = canvasRef.current; const ctx = c.getContext("2d"); ctx.lineWidth = 2; ctx.lineCap = "round"; ctx.strokeStyle = C.navy; const { x, y } = pos(e, c); ctx.lineTo(x, y); ctx.stroke(); };
  const end = (e) => { e.preventDefault(); drawing.current = false; setHasSig(true); onChange(canvasRef.current.toDataURL()); };
  const clear = () => { canvasRef.current.getContext("2d").clearRect(0, 0, 400, 150); setHasSig(false); onChange(null); };

  return (
    <div>
      <div style={{ border: `1.5px solid ${C.border}`, borderRadius: 8, overflow: "hidden", background: "#FAFBFD", touchAction: "none" }}>
        <canvas ref={canvasRef} width={400} height={150}
          style={{ display: "block", width: "100%", height: 150, cursor: "crosshair" }}
          onMouseDown={start} onMouseMove={move} onMouseUp={end} onMouseLeave={end}
          onTouchStart={start} onTouchMove={move} onTouchEnd={end} />
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 6 }}>
        <span style={{ fontSize: 12, color: C.textMuted }}>{hasSig ? "✅ Signature enregistrée" : "Signez dans le cadre ci-dessus"}</span>
        {hasSig && <button onClick={clear} style={{ border: "none", background: "none", color: C.danger, fontSize: 12, cursor: "pointer", fontWeight: 600 }}>Effacer</button>}
      </div>
    </div>
  );
}

// ── Composant : Annotation photo ───────────────────────────────────────────
function PhotoAnnotator({ src, onSave, onClose }) {
  const canvasRef = useRef(null);
  const drawing = useRef(false);
  const [color, setColor] = useState("#E8642A");
  const [size, setSize] = useState(3);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    const img = new Image();
    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;
      ctx.drawImage(img, 0, 0);
    };
    img.src = src;
  }, [src]);

  const pos = (e) => {
    const r = canvasRef.current.getBoundingClientRect();
    const src2 = e.touches ? e.touches[0] : e;
    const scaleX = canvasRef.current.width / r.width;
    const scaleY = canvasRef.current.height / r.height;
    return { x: (src2.clientX - r.left) * scaleX, y: (src2.clientY - r.top) * scaleY };
  };

  const start = (e) => { e.preventDefault(); drawing.current = true; const ctx = canvasRef.current.getContext("2d"); const { x, y } = pos(e); ctx.beginPath(); ctx.moveTo(x, y); };
  const move = (e) => {
    e.preventDefault();
    if (!drawing.current) return;
    const ctx = canvasRef.current.getContext("2d");
    ctx.lineWidth = size; ctx.lineCap = "round"; ctx.strokeStyle = color;
    const { x, y } = pos(e);
    ctx.lineTo(x, y); ctx.stroke();
  };
  const end = (e) => { e.preventDefault(); drawing.current = false; };

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.85)", zIndex: 1000, display: "flex", flexDirection: "column" }}>
      {/* Toolbar */}
      <div style={{ background: C.navy, padding: "10px 16px", display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
        <span style={{ color: "#fff", fontWeight: 700, fontSize: 14 }}>✏️ Annoter la photo</span>
        <div style={{ display: "flex", gap: 6, marginLeft: "auto" }}>
          {["#E8642A", "#D94040", "#2A9D63", "#1B2A4A", "#fff"].map(col => (
            <button key={col} onClick={() => setColor(col)}
              style={{ width: 26, height: 26, borderRadius: "50%", background: col, border: color === col ? "3px solid #fff" : "2px solid rgba(255,255,255,0.3)", cursor: "pointer" }} />
          ))}
        </div>
        <div style={{ display: "flex", gap: 6 }}>
          {[2, 4, 8].map(s => (
            <button key={s} onClick={() => setSize(s)}
              style={{ width: 30, height: 30, borderRadius: 6, background: size === s ? "rgba(255,255,255,0.3)" : "rgba(255,255,255,0.1)", border: "none", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}>
              <div style={{ width: s * 2, height: s * 2, borderRadius: "50%", background: "#fff" }} />
            </button>
          ))}
        </div>
      </div>
      {/* Canvas */}
      <div style={{ flex: 1, overflow: "auto", display: "flex", alignItems: "center", justifyContent: "center", padding: 12, touchAction: "none" }}>
        <canvas ref={canvasRef}
          style={{ maxWidth: "100%", maxHeight: "100%", cursor: "crosshair", borderRadius: 8 }}
          onMouseDown={start} onMouseMove={move} onMouseUp={end} onMouseLeave={end}
          onTouchStart={start} onTouchMove={move} onTouchEnd={end} />
      </div>
      {/* Actions */}
      <div style={{ background: C.navy, padding: "10px 16px", display: "flex", gap: 10 }}>
        <button onClick={onClose} style={{ flex: 1, border: "1.5px solid rgba(255,255,255,0.3)", borderRadius: 8, padding: "10px", background: "none", color: "#fff", fontWeight: 600, cursor: "pointer", fontSize: 14 }}>Annuler</button>
        <button onClick={() => { onSave(canvasRef.current.toDataURL()); onClose(); }}
          style={{ flex: 2, border: "none", borderRadius: 8, padding: "10px", background: C.orange, color: "#fff", fontWeight: 700, cursor: "pointer", fontSize: 14 }}>
          Enregistrer l'annotation
        </button>
      </div>
    </div>
  );
}

// ── Composant : Photo upload avec annotation ───────────────────────────────
function PhotoUpload({ photos, onChange }) {
  const inputRef = useRef(null);
  const [annotating, setAnnotating] = useState(null); // index de la photo à annoter

  const addPhotos = (e) => {
    const files = Array.from(e.target.files);
    Promise.all(files.map(f => new Promise(res => {
      const r = new FileReader();
      r.onload = ev => res(ev.target.result);
      r.readAsDataURL(f);
    }))).then(imgs => onChange([...photos, ...imgs]));
    e.target.value = "";
  };

  const remove = (i) => onChange(photos.filter((_, idx) => idx !== i));
  const saveAnnotation = (i, data) => onChange(photos.map((p, idx) => idx === i ? data : p));

  return (
    <div>
      {annotating !== null && (
        <PhotoAnnotator
          src={photos[annotating]}
          onSave={(data) => saveAnnotation(annotating, data)}
          onClose={() => setAnnotating(null)}
        />
      )}
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        {photos.map((src, i) => (
          <div key={i} style={{ position: "relative", width: 80, height: 80 }}>
            <img src={src} alt="" style={{ width: 80, height: 80, objectFit: "cover", borderRadius: 8, border: `1px solid ${C.border}` }} />
            {/* Bouton annoter */}
            <button onClick={() => setAnnotating(i)}
              style={{ position: "absolute", bottom: -6, left: -6, width: 22, height: 22, borderRadius: "50%", background: C.steel, border: "none", color: "#fff", fontSize: 11, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}>
              ✏️
            </button>
            {/* Bouton supprimer */}
            <button onClick={() => remove(i)}
              style={{ position: "absolute", top: -6, right: -6, width: 22, height: 22, borderRadius: "50%", background: C.danger, border: "none", color: "#fff", fontSize: 13, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}>
              ×
            </button>
          </div>
        ))}
        <button onClick={() => inputRef.current.click()}
          style={{ width: 80, height: 80, border: `2px dashed ${C.border}`, borderRadius: 8, background: C.bg, cursor: "pointer", fontSize: 24, color: C.textMuted, display: "flex", alignItems: "center", justifyContent: "center" }}>
          +
        </button>
      </div>
      {photos.length > 0 && <div style={{ fontSize: 11, color: C.textMuted, marginTop: 6 }}>Appuyez sur ✏️ pour annoter une photo</div>}
      <input ref={inputRef} type="file" accept="image/*" multiple style={{ display: "none" }} onChange={addPhotos} />
    </div>
  );
}

// ── Composant : Matériaux ──────────────────────────────────────────────────
function MateriauxEditor({ items, onChange }) {
  const add = () => onChange([...items, { nom: "", qte: "1" }]);
  const update = (i, key, val) => onChange(items.map((m, idx) => idx === i ? { ...m, [key]: val } : m));
  const remove = (i) => onChange(items.filter((_, idx) => idx !== i));

  return (
    <div>
      {items.length > 0 && (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 70px 28px", gap: 6, marginBottom: 4 }}>
          <span style={{ fontSize: 11, fontWeight: 700, color: C.textMuted, paddingLeft: 4 }}>DÉSIGNATION</span>
          <span style={{ fontSize: 11, fontWeight: 700, color: C.textMuted, textAlign: "center" }}>QTÉ</span>
          <span />
        </div>
      )}
      {items.map((m, i) => (
        <div key={i} style={{ display: "grid", gridTemplateColumns: "1fr 70px 28px", gap: 6, marginBottom: 6, alignItems: "center" }}>
          <input value={m.nom} onChange={e => update(i, "nom", e.target.value)} placeholder="ex: Joint, câble…" style={inputSt} />
          <input value={m.qte} onChange={e => update(i, "qte", e.target.value)} placeholder="1" type="number" min="0" style={{ ...inputSt, textAlign: "center" }} />
          <button onClick={() => remove(i)} style={{ border: "none", background: "none", color: C.danger, fontSize: 20, cursor: "pointer", fontWeight: 700, lineHeight: 1 }}>×</button>
        </div>
      ))}
      <button onClick={add} style={{ border: `1.5px dashed ${C.steel}`, background: "none", color: C.steel, borderRadius: 7, padding: "7px 14px", fontSize: 13, fontWeight: 600, cursor: "pointer", marginTop: 4 }}>
        + Ajouter un matériau
      </button>
    </div>
  );
}

// ── Composant : Liste de tâches ────────────────────────────────────────────
function TachesEditor({ taches, onChange }) {
  const [newLabel, setNewLabel] = useState("");

  const toggle = (i) => onChange(taches.map((t, idx) => idx === i ? { ...t, fait: !t.fait } : t));
  const addCustom = () => {
    const label = newLabel.trim();
    if (!label) return;
    onChange([...taches, { label, fait: false, base: false }]);
    setNewLabel("");
  };
  const remove = (i) => onChange(taches.filter((_, idx) => idx !== i));

  const done = taches.filter(t => t.fait).length;

  return (
    <div>
      {/* Barre de progression */}
      <div style={{ marginBottom: 14 }}>
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 5 }}>
          <span style={{ fontSize: 12, color: C.textMuted, fontWeight: 600 }}>{done}/{taches.length} tâches effectuées</span>
          {done === taches.length && taches.length > 0 && <span style={{ fontSize: 12, color: C.success, fontWeight: 700 }}>✅ Tout terminé !</span>}
        </div>
        <div style={{ height: 6, background: C.border, borderRadius: 99, overflow: "hidden" }}>
          <div style={{ height: "100%", width: `${taches.length ? (done / taches.length) * 100 : 0}%`, background: done === taches.length ? C.success : "#AAAAAA", borderRadius: 99, transition: "width 0.3s" }} />
        </div>
      </div>

      {/* Liste */}
      <div style={{ display: "flex", flexDirection: "column", gap: 6, marginBottom: 12 }}>
        {taches.map((t, i) => (
          <div key={i} style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 12px", background: t.fait ? "#E6F7EF" : C.bg, borderRadius: 8, border: `1.5px solid ${t.fait ? C.success + "55" : C.border}`, transition: "all 0.15s" }}>
            <button onClick={() => toggle(i)}
              style={{ width: 22, height: 22, borderRadius: 6, border: `2px solid ${t.fait ? C.success : C.border}`, background: t.fait ? C.success : "#fff", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, transition: "all 0.15s" }}>
              {t.fait && <span style={{ color: "#fff", fontSize: 13, fontWeight: 700 }}>✓</span>}
            </button>
            <span style={{ flex: 1, fontSize: 14, color: t.fait ? C.success : C.text, textDecoration: t.fait ? "line-through" : "none", fontWeight: t.fait ? 500 : 400 }}>{t.label}</span>
            {!t.base && (
              <button onClick={() => remove(i)} style={{ border: "none", background: "none", color: C.textMuted, fontSize: 16, cursor: "pointer", padding: "0 4px" }}>×</button>
            )}
          </div>
        ))}
      </div>

      {/* Ajouter tâche custom */}
      <div style={{ display: "flex", gap: 8 }}>
        <input value={newLabel} onChange={e => setNewLabel(e.target.value)}
          onKeyDown={e => e.key === "Enter" && addCustom()}
          placeholder="Ajouter une tâche spécifique…"
          style={{ ...inputSt, flex: 1 }} />
        <button onClick={addCustom}
          style={{ border: "none", background: C.steel, color: "#fff", borderRadius: 8, padding: "0 14px", fontWeight: 700, fontSize: 18, cursor: "pointer" }}>+</button>
      </div>
    </div>
  );
}


